examples:
TypeScript: // minimal InvokeStream usage example
const stream = client.invokeStream({model: 'rw-13b', input: prompt});
for await (const ev of stream) {
  if (ev.type === 'chunk') process.stdout.write(ev.value);
  if (ev.type === 'tool_call') await handleTool(ev.value);
}

Python: # async generator InvokeStream example
async for ev in client.invoke_stream(model='rw-13b', input=prompt):
    if ev['type'] == 'chunk': print(ev['value'], end='')
    if ev['type'] == 'tool_call': await handle_tool(ev['value'])

Go: // channel-based InvokeStream example
stream := client.InvokeStream(ctx, &InvokeRequest{Model: "rw-13b", Input: prompt})
for ev := range stream.Events {
    switch ev.Type {
    case "chunk": fmt.Print(ev.Value)
    case "tool_call": go handleTool(ev.Value)
    }
}
